package com.scpfoundation;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** One SCP entry, loaded from scp_registry.json (generated by tools/generate_resources.py). */
public record ScpDefinition(int n, String id, String name, String cls, String form, boolean canon,
                            List<String> behaviors, int hp, int dmg, List<String> recipe,
                            double scale, String sizeSrc) {

	public boolean isEntity() { return form.equals("entity"); }
	public boolean isBlock() { return form.equals("block"); }
	public boolean isItem() { return form.equals("item"); }

	public String title() {
		return "SCP-" + String.format("%04d", n) + ": " + name;
	}

	public static List<ScpDefinition> loadAll() {
		List<ScpDefinition> out = new ArrayList<>();
		try (Reader r = new InputStreamReader(
				ScpDefinition.class.getResourceAsStream("/scp_registry.json"), StandardCharsets.UTF_8)) {
			JsonArray arr = JsonParser.parseReader(r).getAsJsonObject().getAsJsonArray("entries");
			for (JsonElement el : arr) {
				JsonObject o = el.getAsJsonObject();
				List<String> beh = new ArrayList<>();
				for (JsonElement b : o.getAsJsonArray("behaviors")) beh.add(b.getAsString());
				List<String> rec = new ArrayList<>();
				for (JsonElement b : o.getAsJsonArray("recipe")) rec.add(b.getAsString());
				out.add(new ScpDefinition(o.get("n").getAsInt(), o.get("id").getAsString(), o.get("name").getAsString(),
						o.get("cls").getAsString(), o.get("form").getAsString(), o.get("canon").getAsBoolean(),
						beh, o.get("hp").getAsInt(), o.get("dmg").getAsInt(), rec,
						o.get("scale").getAsDouble(), o.get("size_src").getAsString()));
			}
		} catch (Exception e) {
			throw new IllegalStateException("Could not read scp_registry.json", e);
		}
		return out;
	}
}
